<#
.SYNOPSIS
    Write the configure-check results of a CMakeCache.txt as a `cmake -C` preload script (#1406).
.DESCRIPTION
    Called by the cmake-check-cache action after an unseeded configure. Keeps only the entries that
    CMake's check modules write, recognised by the help text those modules give them:

      check_c_source_compiles / check_*_compiler_flag / check_*_source_runs  "Test <VAR>"
      check_include_file(s)                                                 "Have include(s) <h>"
      check_symbol_exists / check_cxx_symbol_exists                         "Have symbol <sym>"
      check_function_exists                                                 "Have function <fn>"
      check_library_exists                                                  "Have library <lib>"
      check_variable_exists                                                 "Have variable <var>"

    and only with the values those modules store (1 for a pass, empty for a fail). Each module
    skips its test when its result variable is already defined, so preloading these makes a later
    configure skip the try_compile. Anything else (option() values, find results, compiler
    detection, try_compile results with other help texts, check_type_size) is left out, so it is
    computed afresh.
.PARAMETER CachePath
    The CMakeCache.txt of the configure to export.
.PARAMETER OutPath
    The preload script to write.
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$CachePath,
    [Parameter(Mandatory)][string]$OutPath
)

$ErrorActionPreference = 'Stop'

$docPattern = '^//(Test |Have (include|includes|symbol|function|library|variable) )'
$entryPattern = '^([A-Za-z0-9_]+):INTERNAL=(1?)$'

$lines = [IO.File]::ReadAllLines($CachePath)
$out = [Collections.Generic.List[string]]::new()
$out.Add("# CMake configure-check results exported from an unseeded configure (#1406).")
$out.Add("# Generated by .github/actions/cmake-check-cache; do not edit.")
$count = 0
for ($i = 1; $i -lt $lines.Length; $i++) {
    $match = [regex]::Match($lines[$i].TrimEnd("`r"), $entryPattern)
    if (-not $match.Success) { continue }
    if ($lines[$i - 1] -notmatch $docPattern) { continue }
    $out.Add(('set({0} "{1}" CACHE INTERNAL "{2}")' -f $match.Groups[1].Value, $match.Groups[2].Value, 'Seeded configure check result'))
    $count++
}

$dir = Split-Path -Parent $OutPath
if ($dir) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
[IO.File]::WriteAllLines($OutPath, $out)
Write-Host "Exported $count configure-check results from $CachePath to $OutPath"
if ($count -eq 0) {
    # An empty seed would be harmless but means the export no longer recognises CMake's entries;
    # say so rather than caching it.
    Write-Host "::warning title=No configure-check results::nothing matched in $CachePath; not caching a seed"
    Remove-Item -LiteralPath $OutPath
}
